const P = '<CORREO>';
const c = (caso, esperado, correo_id, fecha_hora, de, adjunto, decision, extra = {}) =>
  ({ json: { caso, esperado, decision, correo_id, fecha_hora, de, para: P, asunto: 'Factura ' + adjunto, cuerpo: 'Adjuntamos la factura. Saludos.', adjunto, ...extra } });
// decision: lo que la prueba simula que deciden las personas (en la realidad, en el formulario del 8.3)
return [
  c('1 factura normal, aprobada', 'L3 al Gerente; queda Aprobada para pago', 'COR-002', '2026-10-26 17:24', '<CORREO>', 'LOTE-002.pdf', 'aprobar'),
  c('2 más de $ 5.000.000, aprueban los dos', 'Doble control; queda Aprobada para pago', 'COR-040', '2026-10-12 11:05', '<CORREO>', 'LOTE-040.pdf', 'aprobar_los_dos'),
  c('3 más de $ 5.000.000, falta el segundo', 'Doble control; sigue Registrada esperando al Socio gerente', 'COR-091', '2026-10-09 08:55', '<CORREO>', 'LOTE-091.pdf', 'solo_primer_paso'),
  c('4 monotributista, rechazada', 'L3; queda En espera y va a la cola', 'PRUEBA-MONO-1', '2026-10-15 10:00', '<CORREO>', 'MONO-PRV-121.pdf', 'rechazar', { carpeta: 'pruebas_extra' }),
];

const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
return $input.all().map((i) => ({ json: { ...i.json, prefijo_id: prefijo } }));

// Simula las decisiones del formulario con la misma función de la base que usa el formulario (registrar_decision).
const casos = $('CA84dP_Casos').all().map((i) => i.json);
const out = [];
$input.all().forEach((i, k) => { const r = i.json, d = casos[k].decision;
  if (!r.aprobacion_id) return;
  const paso = (quien, decision, motivo) => out.push({ json: { aprobacion_id: String(r.aprobacion_id), quien, decision, motivo } });
  if (d === 'aprobar') paso(r.aprobador, 'aprobado', 'PRUEBA 8.4d: controles completos');
  if (d === 'aprobar_los_dos') { paso(r.aprobador, 'aprobado', 'PRUEBA 8.4d: primer paso'); paso(r.segundo_aprobador, 'aprobado', 'PRUEBA 8.4d: segundo paso'); }
  if (d === 'solo_primer_paso') paso(r.aprobador, 'aprobado', 'PRUEBA 8.4d: primer paso');
  if (d === 'rechazar') paso(r.aprobador, 'rechazado', 'PRUEBA 8.4d: la obra se suspendió');
});
return out;

const casos = $('CA84dP_Casos').all().map((i) => i.json);
const p = $('CA84dP_Pedir_aprobacion').all().map((i) => i.json);
const act = $input.first().json;
const fin = (id) => { const c = (act.cambios || []).find((x) => x.comprobante_id === id); return c ? c.estado : ((act.pendientes || []).includes(id) ? 'Registrada' : 'sin cambio'); };
const ok = [
  (r, f) => r.nivel === 'L3' && r.aprobador === 'Gerente de Administración' && f === 'Aprobada para pago',
  (r, f) => r.nivel === 'L3 + doble control' && r.segundo_aprobador === 'Socio gerente' && f === 'Aprobada para pago',
  (r, f) => r.nivel === 'L3 + doble control' && f === 'Registrada',
  (r, f) => r.nivel === 'L3' && f === 'En espera',
];
return casos.map((c, i) => { const r = p[i] || {}; const f = fin(r.comprobante_id);
  let pasa = false; try { pasa = r.estado === 'Registrada' && !!r.link_formulario && ok[i](r, f); } catch (e) {}
  return { json: { caso: c.caso, esperado: c.esperado, resultado: pasa ? 'PASA' : 'FALLA',
    detalle: JSON.stringify({ registro: r.estado, aprobacion: r.aprobacion_id, nivel: r.nivel, aprobador: r.aprobador, segundo: r.segundo_aprobador, vence: r.vence, estado_final: f, motivo: r.motivo }) } }; });
